-- Spider Grab Mechanic Script\n\nlocal Players = game:GetService("Players")\nlocal UserInputService = game:GetService("UserInputService")\n\nlocal function onInputBegan(input, gameProcessed)\n    if input.UserInputType == Enum.UserInputType.MouseButton2 and not gameProcessed then\n        local character = Players.LocalPlayer.Character\n        if character then\n            local humanoid = character:FindFirstChildOfClass("Humanoid")\n            if humanoid then\n                local target = nil\n                local raycastParams = RaycastParams.new()\n                raycastParams.FilterDescendantsInstances = {character}\n                raycastParams.FilterType = Enum.RaycastFilterType.Blacklist\n                \n                local raycastResult = workspace:Raycast(character.HumanoidRootPart.Position, character.HumanoidRootPart.CFrame.LookVector * 10, raycastParams)\n                \n                if raycastResult then\n                    target = raycastResult.Instance:FindFirstAncestorOfClass("Model")\n                end\n                \n                if target and target:FindFirstChild("Humanoid") then\n                    local targetHumanoid = target.Humanoid\n                    local constraint = Instance.new("RopeConstraint")\n                    constraint.Attachment0 = Instance.new("Attachment")\n                    constraint.Attachment0.Parent = character.HumanoidRootPart\n                    constraint.Attachment1 = Instance.new("Attachment")\n                    constraint.Attachment1.Parent = targetHumanoid.RootPart\n                    constraint.Parent = character.HumanoidRootPart\n                    \n                    local function onInputEnded(inputEnd, gameProcessedEnd)\n                        if inputEnd.UserInputType == Enum.UserInputType.MouseButton2 then\n                            constraint:Destroy()\n                            UserInputService.InputEnded:Disconnect()\n                        end\n                    end\n                    \n                    UserInputService.InputEnded:Connect(onInputEnded)\n                end\n            end\n        end\n    end\nend\n\nUserInputService.InputBegan:Connect(onInputBegan)\